def countDistinctWindows(s, k):
    cnt = {}
    repeats = 0
    ans = 0
    for i, ch in enumerate(s):
        c = cnt.get(ch, 0) + 1
        cnt[ch] = c
        if c == 2:
            repeats += 1
        if i >= k:
            old = s[i - k]
            c = cnt[old]
            cnt[old] = c - 1
            if c == 2:
                repeats -= 1
        if i >= k - 1 and repeats == 0:
            ans += 1
    return ans
